negativeExample:
import java.io.FileInputStream;
import java.io.InputStream;
import java.io.File;
import org.eclipse.core.resources.IFile;
import org.eclipse.core.resources.IResource;
import org.eclipse.core.runtime.CoreException;
import org.eclipse.core.runtime.IProgressMonitor;
import org.eclipse.core.runtime.NullProgressMonitor;

public class Example {
    public void createFileFromPath(IFile file, File sourceFile) throws CoreException {
        IProgressMonitor monitor = new NullProgressMonitor();
        // Should not match: using FileInputStream, not ByteArrayInputStream
        try (InputStream stream = new FileInputStream(sourceFile)) {
            file.create(stream, IResource.FORCE, monitor);
        } catch (java.io.IOException e) {
            // handle exception
        }
    }
}
